# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_cloudflared_tunnel() {
    _argc_util_cache 300 _helper_cloudflared_tunnels_uncached cloudflared__tunnels
}

_choice_cloudflared_vnet() {
    _argc_util_cache 300 _helper_cloudflared_vnets_uncached cloudflared__vnets
}

_helper_cloudflared_tunnels_uncached() {
    cloudflared tunnel list -o json 2>/dev/null |
        jq -b -r '.. | objects | select(has("name") and has("id")) | .name, .id' 2>/dev/null
}

_helper_cloudflared_vnets_uncached() {
    cloudflared tunnel vnet list -o json 2>/dev/null |
        jq -b -r '.. | objects | select(has("name") and has("id")) | .name, .id' 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
